class Solution:
    def concatHex36(self, n: int) -> str:
        D = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        def conv(v, b):
            if v == 0: return "0"
            s = ""
            while v:
                s = D[v % b] + s
                v //= b
            return s
        return conv(n * n, 16) + conv(n ** 3, 36)

