class Solution {
    private String conv(long v, int b) {
        final String D = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        if (v == 0) return "0";
        StringBuilder sb = new StringBuilder();
        while (v > 0) { sb.append(D.charAt((int)(v % b))); v /= b; }
        return sb.reverse().toString();
    }
    public String concatHex36(int n) {
        return conv((long) n * n, 16) + conv((long) n * n * n, 36);
    }
}

