class Solution {
    public String concatHex36(int n) {
        String hexPart = Long.toString((long) n * n, 16).toUpperCase();
        final String D = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        long v = (long) n * n * n;
        StringBuilder sb = new StringBuilder();
        if (v == 0) sb.append('0');
        while (v > 0) { sb.append(D.charAt((int)(v % 36))); v /= 36; }
        return hexPart + sb.reverse().toString();
    }
}

